SELECT CASE WHEN s.rating >= 3.7 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(DISTINCT i.quantity) AS unique_stores, MIN(i.last_restock) AS min_last_restock FROM inventory i JOIN products p ON i.product_id = p.id LEFT JOIN suppliers s ON s.id = p.supplier_id WHERE i.store_id IN (1, 3) GROUP BY CASE WHEN s.rating >= 3.7 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket DESC
